-- phase: data
-- compatible-from: *
-- compatible-to: *
-- maintenance: false
-- Migration 553: reporting catalogue entries for assets running a tray agent
-- older than a chosen version. The version comes from the tray agent linked to
-- the asset, not the RMM agent, so old tray agents that cannot run the RMM
-- agent are still listed. Idempotent via INSERT IGNORE on the unique slug.
INSERT IGNORE INTO reporting_queries (slug, name, description, category, sql_query, is_system)
VALUES
('tray-agent-below-version', 'Tray: Assets with Tray Agent Below Version', 'Assets whose tray agent version is lower than a set version, read from the tray agent linked to each asset rather than the RMM agent, so devices too old to run the RMM agent still appear. Edit the ''1.0.0'' value in the query to set the version to compare against.', 'Tray', 'SELECT c.name AS company, a.id AS asset_id, a.name AS device, a.serial_number, v.hostname, v.os, v.tray_version, p.below_version, v.last_seen_utc FROM assets a JOIN (SELECT td.asset_id, td.hostname, td.os, TRIM(LEADING ''v'' FROM LOWER(TRIM(td.agent_version))) AS tray_version, td.last_seen_utc FROM tray_devices td WHERE td.status = ''active'' AND td.asset_id IS NOT NULL) v ON v.asset_id = a.id CROSS JOIN (SELECT ''1.0.0'' AS below_version) p LEFT JOIN companies c ON c.id = a.company_id WHERE v.tray_version IS NOT NULL AND v.tray_version <> '''' AND CONCAT(LPAD(SUBSTRING_INDEX(v.tray_version, ''.'', 1) + 0, 6, ''0''), LPAD(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(v.tray_version, ''.0.0''), ''.'', 2), ''.'', -1) + 0, 6, ''0''), LPAD(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(v.tray_version, ''.0.0''), ''.'', 3), ''.'', -1) + 0, 6, ''0'')) < CONCAT(LPAD(SUBSTRING_INDEX(p.below_version, ''.'', 1) + 0, 6, ''0''), LPAD(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(p.below_version, ''.0.0''), ''.'', 2), ''.'', -1) + 0, 6, ''0''), LPAD(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(p.below_version, ''.0.0''), ''.'', 3), ''.'', -1) + 0, 6, ''0'')) ORDER BY company, v.tray_version, device', 1),
('tray-agent-below-version-company-scoped', 'Tray: Assets with Tray Agent Below Version (Company Scoped)', 'Assets whose tray agent version is lower than a set version, read from the tray agent linked to each asset rather than the RMM agent, so devices too old to run the RMM agent still appear. Edit the ''1.0.0'' value in the query to set the version to compare against. Company scoped: limited to the company the report is run for.', 'Tray', 'SELECT c.name AS company, a.id AS asset_id, a.name AS device, a.serial_number, v.hostname, v.os, v.tray_version, p.below_version, v.last_seen_utc FROM assets a JOIN (SELECT td.asset_id, td.hostname, td.os, TRIM(LEADING ''v'' FROM LOWER(TRIM(td.agent_version))) AS tray_version, td.last_seen_utc FROM tray_devices td WHERE td.status = ''active'' AND td.asset_id IS NOT NULL) v ON v.asset_id = a.id CROSS JOIN (SELECT ''1.0.0'' AS below_version) p LEFT JOIN companies c ON c.id = a.company_id WHERE a.company_id = {{current.company}} AND v.tray_version IS NOT NULL AND v.tray_version <> '''' AND CONCAT(LPAD(SUBSTRING_INDEX(v.tray_version, ''.'', 1) + 0, 6, ''0''), LPAD(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(v.tray_version, ''.0.0''), ''.'', 2), ''.'', -1) + 0, 6, ''0''), LPAD(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(v.tray_version, ''.0.0''), ''.'', 3), ''.'', -1) + 0, 6, ''0'')) < CONCAT(LPAD(SUBSTRING_INDEX(p.below_version, ''.'', 1) + 0, 6, ''0''), LPAD(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(p.below_version, ''.0.0''), ''.'', 2), ''.'', -1) + 0, 6, ''0''), LPAD(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(p.below_version, ''.0.0''), ''.'', 3), ''.'', -1) + 0, 6, ''0'')) ORDER BY company, v.tray_version, device', 1);
